function pigWord(w){
  if(/^[^a-zA-Z]*$/.test(w)) return w;
  var m=w.match(/^([a-zA-Z]+)(.*)$/);
  if(!m) return w;
  var letters=m[1], tail=m[2];
  var lower=letters.toLowerCase();
  var idx=lower.search(/[aeiou]/);
  if(idx<=0) return letters+'way'+tail;
  var cons=letters.slice(0,idx), rest=letters.slice(idx);
  return rest+cons+'ay'+tail;
}
function toPigLatin(text){
  if(!text) return {error:'请输入英文文本'};
  var parts=text.split(/(\s+)/);
  var out=parts.map(function(t){ if(/^\s+$/.test(t)) return t; return pigWord(t); });
  return {value:out.join(''), translated:out.join('')};
}
var EXPORTS={toPigLatin:toPigLatin};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PigLatinForgePure = EXPORTS; }
